/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const pageIndex = "" + dma_page.get("currentPage") + "";
        const pageObj = $('.paging td:contains(' + pageIndex + ')');
        const pagingLeng = $('.paging td:contains(' + pageIndex + ')').length;
        for (let i = 0; i < pagingLeng; i++) {
            const obj = pageObj[i];
            const val = $(obj).text();
            if (pageIndex !== val) {
                continue;
            }
            const font = "<font color='blue'>" + val + "</font>";
            $(obj).html(font);
            $(obj).attr("style", "font-size:15px;");
        }
        let temp = $c.util.getComponent('ipt_checkWhere').getValue(); if (temp == null) { temp = ''; }
        if (temp === "" || temp === "all") {
            $("input[name=bnd_tp_cd]").attr("checked", "checked");
        } else {
            /* 수동 전환 필요: 이름 선택자 순회 [name=bnd_tp_cd] — B4 반복 밖 동명 입력(정적/계수 틀) · to-be 에 돌 요소가 없다 */ $("input[name=bnd_tp_cd]").each(function() {
                    if (temp.match($(this).val())) {
                        $(this).attr("checked", "checked");
                    }
            });
        }
        if ($("input[name=bnd_tp_cd]").length === $("input[name=bnd_tp_cd]:checked").length) {
            $("input[name=check_box]").attr("checked", "checked");
        }
        temp = $c.util.getComponent('ipt_ckKey').getValue(); if (temp == null) { temp = ''; }
        if (temp === "") {
            $("input[name=ch][id=ipt_ch01]").attr("checked", "checked");
            $("input[name=ch][id=ipt_ch02]").attr("checked", "checked");
            $("input[name=ch][id=ipt_ch03]").attr("checked", "checked");
            $("input[name=ch][id=ipt_ch04]").attr("checked", "checked");
        } else {
            /* 수동 전환 필요: 이름 선택자 순회 [name=ch] — B4 반복 밖 동명 입력(정적/계수 틀) · to-be 에 돌 요소가 없다 */ $("input[name=ch]").each(function() {
                    if (temp.match($(this).val())) {
                        $(this).attr("checked", "checked");
                    }
            });
        }
        if ($("input[name=ch]").length === $("input[name=ch]:checked").length) {
            $("input[name=ipt_all]").attr("checked", "checked");
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf25200.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":0,"mmenu":2
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf25200' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.tb1 = $c.util.getComponent('tb1');
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_datefmt_cal_startDD();
        scwin.init_datefmt_cal_endDD();
        scwin.init_datefmt_cal_startIsuDD();
        scwin.init_datefmt_cal_endIsuDD();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf25200.onpageload' });
    }
};

