/**
 * @method
 * @name tx_fnExcelDown
 * @description fn Excel Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnExcelDown = async function () {
    try { return await $c.data.downFile("/down/excel.do?method=searchDownloadBondsExcel", "", ($c.util.getComponent("dma_fnExcelDownReq") ? $c.util.getComponent("dma_fnExcelDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name appDate2
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {String} startId startId
 * @param {String} endId endId
 * @param {*} months months
 * @returns {void}
 * @hidden N
 */
scwin.appDate2 = function (startId, endId, months) { try { const end = $c.date.getServerDateTime(); const start = $c.date.addMonth(end, -Number(months || 0)); const r = function (nm) { return $c.util.getComponent('cal_' + nm) || $c.util.getComponent('ipt_' + nm) || $c.util.getComponent(String(nm)); }; const s = r(String(startId)); if (s && s.setValue) { s.setValue(start); } const e2 = r(String(endId)); if (e2 && e2.setValue) { e2.setValue(end); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'fn_appDate2' }); } };

/**
 * @method
 * @name fnCheckAllEvent
 * @description fn Check All Event 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnCheckAllEvent = function () {
    const form = $("form[name=JLDINF25200]");
    const allChk = $("input[name=ipt_all]").is(":checked");
    if (allChk) {
        $("input[name=ch]", form).attr("checked", "checked");
    } else {
        $("input[name=ch]", form).removeAttr("checked");
    }
};

/**
 * @method
 * @name fnCheckEvent
 * @description fn Check Event 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnCheckEvent = function () {
    const form = $("form[name=JLDINF25200]");
    const len = $("input[name=ch]:checked").length;
    const len1 = $("input[name=ch]").length;
    if (len === len1) {
        $("input[name=ipt_all]", form).attr("checked", "checked");
    } else {
        $("input[name=ipt_all]", form).removeAttr("checked");
    }
};

/**
 * @method
 * @name open_corp_cd
 * @description open corp cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.open_corp_cd = function () {
    formName = (document.JLDINF25200 || { elements: [] });
    fn_popupCorpSearch(formName);
};

/**
 * @method
 * @name SetChecked
 * @description Set Checked 처리
 * @returns {void}
 * @hidden N
 */
scwin.SetChecked = function () {
    const allChk = $("input[name=check_box]").is(":checked");
    if (allChk) {
        $("input[name=bnd_tp_cd]").attr("checked", "checked");
    } else {
        $("input[name=bnd_tp_cd]").removeAttr("checked");
    }
};

/**
 * @method
 * @name toggle
 * @description toggle 처리
 * @returns {void}
 * @hidden N
 */
scwin.toggle = function () {
    $("#searchDiv").toggle();
};

/**
 * @method
 * @name downloadChk
 * @description download Chk 처리
 * @param {*} ipt_type ipt_type
 * @returns {void}
 * @hidden N
 */
scwin.downloadChk = function (ipt_type) {
    if (ipt_type === "1") {
        scwin.tb1.setStyle("display", "");
        $("#tb2").hide();
    } else {
        scwin.tb1.setStyle("display", "none");
        $("#tb2").show();
    }
};

/**
 * @method
 * @name goSearch
 * @description go Search 처리
 * @param {Number} idx idx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goSearch = async function (idx) {
    const form = $("form[name=JLDINF25200]");
    let diff;
    if (idx === 1) {
        if (($c.util.getComponent('cal_startDD').getValue() == null ? '' : String($c.util.getComponent('cal_startDD').getValue())) !== '' || ($c.util.getComponent('cal_endDD').getValue() == null ? '' : String($c.util.getComponent('cal_endDD').getValue())) !== '') {
            if (($c.util.getComponent('cal_startDD').getValue() == null ? '' : String($c.util.getComponent('cal_startDD').getValue())) === '' || ($c.util.getComponent('cal_endDD').getValue() == null ? '' : String($c.util.getComponent('cal_endDD').getValue())) === '') {
                await $c.win.alert("조회기간(코드부여일)의 시작/종료를 정확히 입력하셔야합니다.");
                return;
            } else {
                diff = $c.date.diffDate($c.util.getComponent('cal_startDD').getValue(), $c.util.getComponent('cal_endDD').getValue());
                if (diff > 92) {
                    await $c.win.alert("조회기간(코드부여일)은 3개월 이내로만 가능합니다.");
                    return;
                }
            }
        } else {
            if (($c.util.getComponent('cal_startIsuDD').getValue() == null ? '' : String($c.util.getComponent('cal_startIsuDD').getValue())) !== '' || ($c.util.getComponent('cal_endIsuDD').getValue() == null ? '' : String($c.util.getComponent('cal_endIsuDD').getValue())) !== '') {
                if (($c.util.getComponent('cal_startIsuDD').getValue() == null ? '' : String($c.util.getComponent('cal_startIsuDD').getValue())) === '' || ($c.util.getComponent('cal_endIsuDD').getValue() == null ? '' : String($c.util.getComponent('cal_endIsuDD').getValue())) === '') {
                    await $c.win.alert("조회기간(발행일)의 시작/종료를 정확히 입력하셔야합니다.");
                    return;
                } else {
                    diff = $c.date.diffDate($c.util.getComponent('cal_startIsuDD').getValue(), $c.util.getComponent('cal_endIsuDD').getValue());
                    if (diff > 92) {
                        await $c.win.alert("조회기간(발행일)은 3개월 이내로만 가능합니다.");
                        return;
                    }
                }
            } else {
                if (($c.util.getComponent('cal_startDD').getValue() == null ? '' : String($c.util.getComponent('cal_startDD').getValue())) === '' && ($c.util.getComponent('cal_endDD').getValue() == null ? '' : String($c.util.getComponent('cal_endDD').getValue())) === '' && ($c.util.getComponent('cal_startIsuDD').getValue() == null ? '' : String($c.util.getComponent('cal_startIsuDD').getValue())) === '' && ($c.util.getComponent('cal_endIsuDD').getValue() == null ? '' : String($c.util.getComponent('cal_endIsuDD').getValue())) === '') {
                    await $c.win.alert("조회기간을 입력하셔야합니다.");
                    return;
                }
            }
        }
    }
    const items = $("input[name=ch]:checked").map(function() {
            return $(this).val();
    }).get();
    $c.util.getComponent('ipt_ckKey').setValue(items);
    const kind = $("input[name=bnd_tp_cd]:checked").map(function() {
            return $(this).val();
    }).get();
    $c.util.getComponent('ipt_checkWhere').setValue(kind);
    if (idx === '1') {
        $c.util.getComponent('ipt_pageIndex').setValue("1");
    }
    const url = "/down/downList.do?method=searchDownloadBondsList";
    const fm = (document.JLDINF25200 || { elements: [] });
    fm.action = url;
    fm.target = "_self";
    await $c.data.downFile(url, "", {});
};

